#[test]
fn command_palette_preserves_the_draft_and_runs_existing_commands() {
    let mut app = app();
    for c in "unfinished prompt".chars() {
        app.key(&key(KeyCode::Char(c)), 80);
    }
    let draft = app.editor.text();
    assert!(app.key(&ctrl('p'), 80).is_empty());
    for c in "threads".chars() {
        app.key(&key(KeyCode::Char(c)), 80);
    }
    assert_eq!(app.key(&key(KeyCode::Enter), 80), vec![Action::Threads]);
    assert!(app.overlay.is_none());
    assert_eq!(app.editor.text(), draft);
}

#[test]
fn command_palette_handles_no_matches_and_escape() {
    let mut app = app();
    app.key(&ctrl('p'), 80);
    for c in "zzzzzz".chars() {
        app.key(&key(KeyCode::Char(c)), 80);
    }
    app.key(&key(KeyCode::Down), 80);
    assert!(app.key(&key(KeyCode::Enter), 80).is_empty());
    assert!(matches!(app.overlay, Some(Overlay::Commands { selected: 0, .. })));
    app.key(&key(KeyCode::Esc), 80);
    assert!(app.overlay.is_none());
}

#[test]
fn command_palette_searches_names_and_descriptions() {
    assert_eq!(slash::search("/HELP"), vec![Slash::Help]);
    assert_eq!(slash::search(""), Slash::ALL.to_vec());
    assert!(!slash::search("thread").is_empty());
    assert!(slash::search("zzzzzz").is_empty());
}
